import { headers } from "next/headers";
import { auth, db } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = {
  id: string;
  email: string;
  name: string;
  createdAt: string | number;
};

function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    createdAt: new Date(row.createdAt).toISOString().slice(0, 10),
  };
}

// Users now live in Better Auth's own store (SQLite, see src/lib/auth.ts) —
// this module just reads that "user" table and adapts it to the app's
// existing User shape, so the rest of the app doesn't need to know Better
// Auth exists.
export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare("SELECT id, email, name, createdAt FROM user ORDER BY createdAt ASC")
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare("SELECT id, email, name, createdAt FROM user WHERE id = ?")
    .get(id) as UserRow | undefined;
  return row ? toUser(row) : undefined;
}

// Reads the real signed-in session from the request cookies. Returns
// undefined when nobody is signed in.
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session?.user) return undefined;
  return toUser(session.user);
}

