import { headers } from "next/headers";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(u: { id: string; email: string; name: string; createdAt: Date }): User {
  return {
    id: u.id,
    email: u.email,
    name: u.name,
    createdAt: u.createdAt.toISOString().slice(0, 10),
  };
}

// Users now live in Better Auth's own store (SQLite, see src/lib/auth.ts) —
// this module just adapts that data to the app's existing User shape.
export async function listUsers(): Promise<User[]> {
  const { users } = await auth.api.listUsers({
    query: { limit: 100 },
    headers: await headers(),
  });
  return users.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const user = await auth.api.getUser?.({ query: { id } }).catch(() => undefined);
  if (user) return toUser(user);
  // Fallback: some Better Auth versions don't expose a single-user admin
  // endpoint, so scan the list instead.
  const all = await listUsers();
  return all.find((u) => u.id === id);
}

// Reads the real signed-in session from the request cookies. Returns
// undefined when nobody is signed in.
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session?.user) return undefined;
  return toUser(session.user);
}

