import { NextRequest, NextResponse } from "next/server";
import { getSessionCookie } from "better-auth/cookies";

// This only checks whether a session cookie is present — it does not
// validate the session. It exists purely to redirect signed-out visitors
// before they render the page. The actual check that matters happens
// server-side in the protected page via getCurrentUser() (src/lib/users.ts),
// which verifies the session against the database.
export function middleware(request: NextRequest) {
  const sessionCookie = getSessionCookie(request);

  if (!sessionCookie) {
    const signInUrl = new URL("/sign-in", request.url);
    signInUrl.searchParams.set("from", request.nextUrl.pathname);
    return NextResponse.redirect(signInUrl);
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/dashboard"],
};

