import { redirect } from "next/navigation";
import { getCurrentUser, listUsers } from "@/lib/users";
import { SignOutButton } from "@/components/sign-out-button";

export default async function DashboardPage() {
  // Middleware only checks that a session cookie exists; this is the real
  // check against the database. Redirect here if it turns out the cookie
  // was stale/invalid.
  const me = await getCurrentUser();
  if (!me) {
    redirect("/sign-in?from=/dashboard");
  }

  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-semibold">Dashboard</h1>
        <SignOutButton />
